def _validate_braces(self, format):
        """Check that braces are properly matched in format string."""
        i = 0
        while i < len(format):
            if format[i:i+2] == '{{':
                i += 2
                continue
            if format[i:i+2] == '}}':
                i += 2
                continue
            if format[i] == '{':
                # find matching }
                j = i + 1
                depth = 1
                while j < len(format):
                    if format[j:j+2] == '{{':
                        j += 2
                        continue
                    if format[j:j+2] == '}}':
                        j += 2
                        continue
                    if format[j] == '{':
                        depth += 1
                    elif format[j] == '}':
                        depth -= 1
                        if depth == 0:
                            break
                    j += 1
                if depth != 0:
                    raise ValueError('Missing closing brace in format string')
                i = j + 1
            elif format[i] == '}':
                raise ValueError('Unexpected closing brace in format string')
            else:
                i += 1

